1	/**
2	 * Split Payment routes
3	 *
4	 * POST /api/games/checkout-split  — host initiates a split booking + game + pays their share
5	 * GET  /api/bookings/share/:token — public: get split booking info (for invite page)
6	 * POST /api/bookings/share/:token/checkout — invitee pays their share
7	 * GET  /api/bookings/:bookingId/split-status — host/participant: see all payment statuses
8	 */
9	import { Router, type IRouter } from "express";
10	import { and, eq, ne, sql } from "drizzle-orm";
11	import {
12	  db,
13	  bookingsTable,
14	  courtsTable,
15	  facilitiesTable,
16	  gamesTable,
17	  gameParticipantsTable,
18	  userProfilesTable,
19	  userSportProfilesTable,
20	  courtPricingTable,
21	  courtBlockedSlotsTable,
22	} from "@workspace/db";
23	
24	import { requireAuth, getCurrentUserId } from "../lib/auth";
25	import { getUncachableStripeClient } from "../stripeClient";
26	import { logger } from "../lib/logger";
27	import { z } from "zod";
28	import crypto from "node:crypto";
29	
30	const router: IRouter = Router();
31	
32	// ─── Helpers ─────────────────────────────────────────────────────────────────
33	
34	function toMin(t: string): number {
35	  const [h, m] = t.split(":").map(Number);
36	  return h * 60 + m;
37	}
38	
39	function slotsBetween(startTime: string, endTime: string): string[] {
40	  const slots: string[] = [];
41	  let cur = toMin(startTime);
42	  const end = toMin(endTime);
43	  while (cur < end) {
44	    const h = Math.floor(cur / 60).toString().padStart(2, "0");
45	    const m = (cur % 60).toString().padStart(2, "0");
46	    slots.push(`${h}:${m}`);
47	    cur += 30;
48	  }
49	  return slots;
50	}
51	
52	// ─── POST /api/games/checkout-split ──────────────────────────────────────────
53	
54	const SplitCheckoutBody = z.object({
55	  courtId: z.number().int().positive(),
56	  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
57	  startTime: z.string().regex(/^\d{2}:\d{2}$/),
58	  endTime: z.string().regex(/^\d{2}:\d{2}$/),
59	  totalSlots: z.number().int().min(2).max(8),
60	  sport: z.string().min(1),
61	  skillLevel: z.string().optional().default("any"),
62	  description: z.string().optional(),
63	  customerName: z.string().min(1),
64	  customerEmail: z.string().email(),
65	  customerPhone: z.string().optional(),
66	  // Open match fields
67	  isPublic: z.boolean().optional().default(false),
68	  minSkillLevel: z.number().min(0).max(10).optional(),
69	  maxSkillLevel: z.number().min(0).max(10).optional(),
70	  matchType: z.enum(["casual", "competitive"]).optional().default("casual"),
71	  // Upgrade flow: link an existing casual game instead of creating a new one
72	  linkGameId: z.number().int().positive().optional(),
73	});
74	
75	router.post("/games/checkout-split", requireAuth, async (req, res): Promise<void> => {
76	  const userId = getCurrentUserId(req)!;
77	  const parsed = SplitCheckoutBody.safeParse(req.body);
78	  if (!parsed.success) {
79	    res.status(400).json({ error: parsed.error.message });
80	    return;
81	  }
82	
83	  const {
84	    courtId, date, startTime, endTime, totalSlots, sport, skillLevel, description,
85	    customerName, customerEmail, customerPhone,
86	    isPublic, minSkillLevel, maxSkillLevel, matchType,
87	    linkGameId,
88	  } = parsed.data;
89	
90	  const reqStartMin = toMin(startTime);
91	  const reqEndMin = toMin(endTime);
92	  if (reqEndMin <= reqStartMin) {
93	    res.status(400).json({ error: "endTime must be after startTime" });
94	    return;
95	  }
96	
97	  // ── Fetch court and facility ──────────────────────────────────────────────
98	  const [courtRow] = await db
99	    .select({ court: courtsTable, facility: facilitiesTable })
100	    .from(courtsTable)
101	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
102	    .where(eq(courtsTable.id, courtId));
103	
104	  if (!courtRow?.court) {
105	    res.status(404).json({ error: "Court not found" });
106	    return;
107	  }
108	
109	  const { court, facility } = courtRow;
110	
111	  // ── Server-side price calculation ─────────────────────────────────────────
112	  const dateObj = new Date(`${date}T12:00:00`);
113	  const dayOfWeek = dateObj.getDay();
114	
115	  const pricingEntries = await db.select()
116	    .from(courtPricingTable)
117	    .where(and(
118	      eq(courtPricingTable.courtId, courtId),
119	      eq(courtPricingTable.dayOfWeek, dayOfWeek),
120	    ));
121	
122	  const pricingMap = new Map(pricingEntries.map(e => [e.startTime, Number(e.price)]));
123	  const defaultSlotPrice = Number(court.pricePerHour) / 2;
124	
125	  const slots = slotsBetween(startTime, endTime);
126	  let courtPrice = 0;
127	  for (const slotStart of slots) {
128	    courtPrice += pricingMap.has(slotStart) ? pricingMap.get(slotStart)! : defaultSlotPrice;
129	  }
130	
131	  const totalPrice = courtPrice;
132	  const pricePerSlot = Math.round((totalPrice / totalSlots) * 100) / 100;
133	  const durationMinutes = reqEndMin - reqStartMin;
134	
135	  // ── Conflict check ────────────────────────────────────────────────────────
136	  const conflictingBookings = await db
137	    .select({ startTime: bookingsTable.startTime, endTime: bookingsTable.endTime })
138	    .from(bookingsTable)
139	    .where(and(
140	      eq(bookingsTable.courtId, courtId),
141	      eq(bookingsTable.date, date),
142	      sql`${bookingsTable.status} IN ('confirmed', 'blocked', 'awaiting_players')`,
143	    ));
144	
145	  const recentPending = await db
146	    .select({ startTime: bookingsTable.startTime, endTime: bookingsTable.endTime })
147	    .from(bookingsTable)
148	    .where(and(
149	      eq(bookingsTable.courtId, courtId),
150	      eq(bookingsTable.date, date),
151	      eq(bookingsTable.status, "pending"),
152	      sql`${bookingsTable.createdAt} > NOW() - INTERVAL '15 minutes'`,
153	    ));
154	
155	  const allConflicting = [...conflictingBookings, ...recentPending];
156	  for (const b of allConflicting) {
157	    const bStart = toMin(b.startTime);
158	    const bEnd = toMin(b.endTime);
159	    if (reqStartMin < bEnd && reqEndMin > bStart) {
160	      res.status(409).json({ error: "Pasirinktas laikas užimtas", code: "SLOT_UNAVAILABLE" });
161	      return;
162	    }
163	  }
164	
165	  // Also check blocked slots
166	  const blockedSlots = await db
167	    .select({ startTime: courtBlockedSlotsTable.startTime, endTime: courtBlockedSlotsTable.endTime })
168	    .from(courtBlockedSlotsTable)
169	    .where(and(
170	      eq(courtBlockedSlotsTable.courtId, courtId),
171	      eq(courtBlockedSlotsTable.date, date),
172	    ));
173	
174	  for (const b of blockedSlots) {
175	    const bStart = toMin(b.startTime);
176	    const bEnd = toMin(b.endTime);
177	    if (reqStartMin < bEnd && reqEndMin > bStart) {
178	      res.status(409).json({ error: "Pasirinktas laikas užblokuotas", code: "SLOT_BLOCKED" });
179	      return;
180	    }
181	  }
182	
183	  // ── Create booking ────────────────────────────────────────────────────────
184	  const splitInviteToken = crypto.randomBytes(20).toString("hex");
185	  const datetime = `${date}T${startTime}:00`;
186	
187	  const [booking] = await db.insert(bookingsTable).values({
188	    courtId,
189	    bookerUserId: userId,
190	    customerName,
191	    customerEmail,
