          </button>
          <span className={`text-xs font-medium px-1 tabular-nums ${isToday ? "text-primary" : "text-foreground"}`}>
            {dateLbl}{isToday ? " (šiandien)" : ""}
          </span>
          <button onClick={() => onDateChange(nextDay(selectedDate))} className="p-1 rounded hover:bg-muted transition-colors">
            <ChevronRight className="w-4 h-4" />
          </button>
          {!isToday && (
            <button onClick={() => onDateChange(todayStr())} className="ml-1 text-[10px] text-primary hover:underline">
              šiandien
            </button>
          )}
        </div>
      </div>
      <div className="overflow-x-auto">
        <div className="min-w-[360px] max-h-[340px] overflow-y-auto">
          {SLOTS.map(slot => {
            const slotMin = toMin(slot);
            const slotEnd = addThirty(slot);

            const booking = todayBookings.find(b => {
              const bStart = toMin(b.startTime);
              const bEnd = toMin(b.endTime);
              return bStart <= slotMin && bEnd > slotMin && ["confirmed", "pending", "blocked"].includes(b.status);
            });

            const isNow = isToday && nowMin >= slotMin && nowMin < slotMin + 30;
            const isPast = isPastDay || (isToday && slotMin + 30 <= nowMin);

            const slotPrice = todayPricing[slot] ?? defaultHalf;

            return (
              <div
                key={slot}
                className={`flex items-center border-b border-border/40 last:border-0 px-3 py-1.5 gap-3 min-h-[36px] ${isNow ? "bg-primary/5" : isPast ? "bg-muted/20" : ""}`}
              >
                <span className={`text-xs tabular-nums font-mono w-10 shrink-0 ${isNow ? "text-primary font-bold" : "text-muted-foreground"}`}>
                  {slot}
                </span>
                {booking ? (
                  <div
                    onClick={() => onBookingClick(booking)}
                    className={`flex-1 rounded px-2 py-1 text-xs font-medium border cursor-pointer transition-opacity hover:opacity-75 ${
                      booking.status === "confirmed"
                        ? "bg-blue-500/10 text-blue-700 dark:text-blue-300 border-blue-400/30"
                        : booking.status === "pending"
                          ? "bg-amber-400/15 text-amber-700 dark:text-amber-300 border-amber-400/30"
                          : "bg-zinc-200 dark:bg-zinc-700/50 text-zinc-500 border-zinc-300/40"
                    }`}
                  >
                    <span className="truncate block">{booking.customerName}</span>
                    <span className="text-[10px] opacity-70">{booking.startTime.slice(0, 5)}–{booking.endTime.slice(0, 5)} · {fmtPrice(booking.totalPrice)}</span>

