342	  todayBookings: Booking[];
343	  pricePerHour: number;
344	  todayPricing: Record<string, number>;
345	  selectedDate: string;
346	  isToday: boolean;
347	  onDateChange: (d: string) => void;
348	  onFreeClick: (startTime: string) => void;
349	  onBookingClick: (booking: Booking) => void;
350	}) {
351	  const now = new Date();
352	  const nowMin = now.getHours() * 60 + now.getMinutes();
353	  const defaultHalf = pricePerHour / 2;
354	  const isPastDay = selectedDate < todayStr();
355	  const isFutureDay = selectedDate > todayStr();
356	  const dateLbl = new Date(selectedDate + "T12:00:00").toLocaleDateString("lt-LT", { weekday: "short", day: "numeric", month: "short" });
357	
358	  return (
