366	          <button onClick={() => onDateChange(prevDay(selectedDate))} className="p-1 rounded hover:bg-muted transition-colors">
367	            <ChevronLeft className="w-4 h-4" />
368	          </button>
369	          <span className={`text-xs font-medium px-1 tabular-nums ${isToday ? "text-primary" : "text-foreground"}`}>
370	            {dateLbl}{isToday ? " (šiandien)" : ""}
371	          </span>
372	          <button onClick={() => onDateChange(nextDay(selectedDate))} className="p-1 rounded hover:bg-muted transition-colors">
373	            <ChevronRight className="w-4 h-4" />
374	          </button>
375	          {!isToday && (
376	            <button onClick={() => onDateChange(todayStr())} className="ml-1 text-[10px] text-primary hover:underline">
377	              šiandien
378	            </button>
379	          )}
380	        </div>
381	      </div>
382	      <div className="overflow-x-auto">
383	        <div className="min-w-[360px] max-h-[340px] overflow-y-auto">
384	          {SLOTS.map(slot => {
385	            const slotMin = toMin(slot);
386	            const slotEnd = addThirty(slot);
387	
388	            const booking = todayBookings.find(b => {
389	              const bStart = toMin(b.startTime);
390	              const bEnd = toMin(b.endTime);
391	              return bStart <= slotMin && bEnd > slotMin && ["confirmed", "pending", "blocked"].includes(b.status);
392	            });
393	
394	            const isNow = isToday && nowMin >= slotMin && nowMin < slotMin + 30;
395	            const isPast = isPastDay || (isToday && slotMin + 30 <= nowMin);
396	
397	            const slotPrice = todayPricing[slot] ?? defaultHalf;
398	
399	            return (
400	              <div
401	                key={slot}
402	                className={`flex items-center border-b border-border/40 last:border-0 px-3 py-1.5 gap-3 min-h-[36px] ${isNow ? "bg-primary/5" : isPast ? "bg-muted/20" : ""}`}
403	              >
404	                <span className={`text-xs tabular-nums font-mono w-10 shrink-0 ${isNow ? "text-primary font-bold" : "text-muted-foreground"}`}>
405	                  {slot}
406	                </span>
407	                {booking ? (
408	                  <div
409	                    onClick={() => onBookingClick(booking)}
410	                    className={`flex-1 rounded px-2 py-1 text-xs font-medium border cursor-pointer transition-opacity hover:opacity-75 ${
411	                      booking.status === "confirmed"
412	                        ? "bg-blue-500/10 text-blue-700 dark:text-blue-300 border-blue-400/30"
413	                        : booking.status === "pending"
414	                          ? "bg-amber-400/15 text-amber-700 dark:text-amber-300 border-amber-400/30"
415	                          : "bg-zinc-200 dark:bg-zinc-700/50 text-zinc-500 border-zinc-300/40"
416	                    }`}
417	                  >
418	                    <span className="truncate block">{booking.customerName}</span>
419	                    <span className="text-[10px] opacity-70">{booking.startTime.slice(0, 5)}–{booking.endTime.slice(0, 5)} · {fmtPrice(booking.totalPrice)}</span>
420	                  </div>
421	                ) : (
422	                  <div
423	                    onClick={() => !isPast && onFreeClick(slot)}
424	                    className={`flex-1 flex items-center justify-between rounded border border-dashed border-border/40 px-2 py-1 transition-colors ${
425	                      isPast ? "opacity-40" : "cursor-pointer hover:bg-muted/40 group"
426	                    }`}
427	                  >
428	                    <div className="flex items-center gap-1.5">
429	                      <Plus className="w-3 h-3 text-muted-foreground/40 group-hover:text-muted-foreground/60" />
430	                      <span className="text-[11px] text-muted-foreground/50">{slot}–{slotEnd}</span>
431	                    </div>
432	                    {slotPrice > 0 && (
433	                      <span className="text-[10px] text-muted-foreground/50 font-medium">
434	                        {slotPrice % 1 === 0 ? slotPrice : slotPrice.toFixed(1)}€
435	                      </span>
436	                    )}
437	                  </div>
438	                )}
439	              </div>
440	            );
441	          })}
442	        </div>
443	      </div>
444	    </div>
445	  );
446	}
