599	          )}
600	        </div>
601	        <div className="flex flex-col gap-2 mt-5">
602	          {canCancel && (
603	            <Button
604	              variant="destructive"
605	              className="w-full text-sm"
606	              disabled={cancelMutation.isPending}
607	              onClick={() => cancelMutation.mutate()}
608	            >
609	              {cancelMutation.isPending ? "Atšaukiama…" : booking.status === "blocked" ? "Atblokuoti laiką" : "Atšaukti rezervaciją"}
610	            </Button>
611	          )}
612	          <div className="flex gap-2">
613	            <Button variant="outline" className="flex-1" onClick={onClose}>Uždaryti</Button>
614	            {booking.status !== "blocked" && (
615	              <Button className="flex-1" onClick={() => { onClose(); navigate(`/bookings/${booking.id}`); }}>
616	                Pilna peržiūra
617	              </Button>
618	            )}
619	          </div>
620	        </div>
621	      </div>
622	    </div>
623	  );
624	}
