626	function WeeklyCalendar({ weeklyBookings }: { weeklyBookings: Booking[] }) {
627	  const weekDates = getWeekDates();
628	  const today = todayStr();
629	  const byDate = new Map<string, Booking[]>();
630	  for (const d of weekDates) byDate.set(d, []);
631	  for (const b of weeklyBookings) {
632	    if (byDate.has(b.date)) byDate.get(b.date)!.push(b);
633	  }
634	  return (
635	    <div className="bg-card border border-border rounded-2xl p-4">
636	      <div className="flex items-center gap-2 mb-4">
637	        <CalendarDays className="w-4 h-4 text-primary" />
638	        <h3 className="font-semibold text-sm">Šios savaitės grafikas</h3>
639	      </div>
640	      <div className="grid grid-cols-7 gap-1.5">
641	        {weekDates.map((date, i) => {
642	          const bookings = byDate.get(date) ?? [];
643	          const isToday = date === today;
644	          const isPast = date < today;
645	          const confirmed = bookings.filter(b => b.status === "confirmed").length;
646	          const pending = bookings.filter(b => b.status === "pending").length;
647	          return (
648	            <div key={date} className={`rounded-xl p-2 text-center border transition-colors ${
649	              isToday ? "bg-primary/10 border-primary/30" : isPast ? "bg-muted/30 border-border/50" : "bg-muted/10 border-border"
650	            }`}>
651	              <p className={`text-[10px] font-medium uppercase ${isToday ? "text-primary" : "text-muted-foreground"}`}>{DAY_NAMES[i]}</p>
652	              <p className={`text-xs font-bold mb-1.5 ${isToday ? "text-primary" : "text-foreground"}`}>{fmtDate(date)}</p>
653	              {bookings.length === 0 ? (
654	                <p className="text-[10px] text-muted-foreground">–</p>
655	              ) : (
656	                <div className="space-y-0.5">
657	                  {confirmed > 0 && (
658	                    <div className="rounded bg-emerald-500/15 text-emerald-600 text-[10px] font-semibold px-1 py-0.5">
659	                      {confirmed} ✓
660	                    </div>
661	                  )}
662	                  {pending > 0 && (
663	                    <div className="rounded bg-amber-500/15 text-amber-600 text-[10px] font-semibold px-1 py-0.5">
664	                      {pending} ⏳
665	                    </div>
666	                  )}
667	                </div>
668	              )}
669	            </div>
670	          );
671	        })}
672	      </div>
673	    </div>
674	  );
