function toMin(t: string): number {
  const [h, m] = t.split(":").map(Number);
  return h * 60 + m;
}

function TodayGrid({
  todayBookings,
  pricePerHour,
  todayPricing,
  selectedDate,
  isToday,
  onDateChange,
  onFreeClick,
  onBookingClick,
}: {
  todayBookings: Booking[];
  pricePerHour: number;
  todayPricing: Record<string, number>;
  selectedDate: string;
  isToday: boolean;
  onDateChange: (d: string) => void;
  onFreeClick: (startTime: string) => void;
  onBookingClick: (booking: Booking) => void;
}) {
  const now = new Date();
  const nowMin = now.getHours() * 60 + now.getMinutes();
  const defaultHalf = pricePerHour / 2;
  const isPastDay = selectedDate < todayStr();
  const isFutureDay = selectedDate > todayStr();
  const dateLbl = new Date(selectedDate + "T12:00:00").toLocaleDateString("lt-LT", { weekday: "short", day: "numeric", month: "short" });

  return (
    <div className="bg-card border border-border rounded-2xl overflow-hidden">
      <div className="flex items-center justify-between px-4 py-3 border-b border-border">
        <div className="flex items-center gap-1.5">
          <CalendarDays className="w-4 h-4 text-primary shrink-0" />
          <span className="font-semibold text-sm">Dienos grafikas</span>
        </div>
        <div className="flex items-center gap-1">
          <button onClick={() => onDateChange(prevDay(selectedDate))} className="p-1 rounded hover:bg-muted transition-colors">
            <ChevronLeft className="w-4 h-4" />
          </button>
          <span className={`text-xs font-medium px-1 tabular-nums ${isToday ? "text-primary" : "text-foreground"}`}>
            {dateLbl}{isToday ? " (šiandien)" : ""}
          </span>
          <button onClick={() => onDateChange(nextDay(selectedDate))} className="p-1 rounded hover:bg-muted transition-colors">
            <ChevronRight className="w-4 h-4" />
          </button>
          {!isToday && (
            <button onClick={() => onDateChange(todayStr())} className="ml-1 text-[10px] text-primary hover:underline">
              šiandien
            </button>
          )}
        </div>
      </div>
      <div className="overflow-x-auto">
        <div className="min-w-[360px] max-h-[340px] overflow-y-auto">
          {SLOTS.map(slot => {
            const slotMin = toMin(slot);
            const slotEnd = addThirty(slot);

            const booking = todayBookings.find(b => {
              const bStart = toMin(b.startTime);
              const bEnd = toMin(b.endTime);
              return bStart <= slotMin && bEnd > slotMin && ["confirmed", "pending", "blocked"].includes(b.status);
            });

            const isNow = isToday && nowMin >= slotMin && nowMin < slotMin + 30;
            const isPast = isPastDay || (isToday && slotMin + 30 <= nowMin);

            const slotPrice = todayPricing[slot] ?? defaultHalf;

            return (
              <div
                key={slot}
                className={`flex items-center border-b border-border/40 last:border-0 px-3 py-1.5 gap-3 min-h-[36px] ${isNow ? "bg-primary/5" : isPast ? "bg-muted/20" : ""}`}
              >
                <span className={`text-xs tabular-nums font-mono w-10 shrink-0 ${isNow ? "text-primary font-bold" : "text-muted-foreground"}`}>
                  {slot}
                </span>
                {booking ? (
                  <div
                    onClick={() => onBookingClick(booking)}
                    className={`flex-1 rounded px-2 py-1 text-xs font-medium border cursor-pointer transition-opacity hover:opacity-75 ${
                      booking.status === "confirmed"
                        ? "bg-blue-500/10 text-blue-700 dark:text-blue-300 border-blue-400/30"
                        : booking.status === "pending"
                          ? "bg-amber-400/15 text-amber-700 dark:text-amber-300 border-amber-400/30"
                          : "bg-zinc-200 dark:bg-zinc-700/50 text-zinc-500 border-zinc-300/40"
                    }`}
                  >
                    <span className="truncate block">{booking.customerName}</span>
                    <span className="text-[10px] opacity-70">{booking.startTime.slice(0, 5)}–{booking.endTime.slice(0, 5)} · {fmtPrice(booking.totalPrice)}</span>
                  </div>
                ) : (
                  <div
                    onClick={() => !isPast && onFreeClick(slot)}
                    className={`flex-1 flex items-center justify-between rounded border border-dashed border-border/40 px-2 py-1 transition-colors ${
                      isPast ? "opacity-40" : "cursor-pointer hover:bg-muted/40 group"
                    }`}
                  >
                    <div className="flex items-center gap-1.5">
                      <Plus className="w-3 h-3 text-muted-foreground/40 group-hover:text-muted-foreground/60" />
                      <span className="text-[11px] text-muted-foreground/50">{slot}–{slotEnd}</span>
                    </div>
                    {slotPrice > 0 && (
                      <span className="text-[10px] text-muted-foreground/50 font-medium">
                        {slotPrice % 1 === 0 ? slotPrice : slotPrice.toFixed(1)}€
                      </span>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

const DAY_SHORT_LT = ["Pir", "Ant", "Tre", "Ket", "Pen", "Šeš", "Sek"];

function WeekGrid({
  days, weeklyBookings, pricePerHour, todayPricing,
  onFreeClick, onBookingClick,
}: {
  days: string[];
  weeklyBookings: Booking[];
  pricePerHour: number;
  todayPricing: Record<string, number>;
  onFreeClick: (date: string, startTime: string) => void;
  onBookingClick: (booking: Booking) => void;
}) {
  const today = todayStr();
  const now = new Date();

  return (
    <div className="bg-card border border-border rounded-2xl overflow-hidden">
      <div className="overflow-x-auto">
        <div style={{ minWidth: `${56 + 7 * 90}px` }}>
          {/* Day header */}
          <div className="grid border-b border-border bg-muted/30" style={{ gridTemplateColumns: `56px repeat(7, 1fr)` }}>
            <div className="px-2 py-2" />
            {days.map((day, i) => {
              const isToday = day === today;
              const isPast = day < today;
              const [, mm, dd] = day.split("-");
              return (
                <div key={day} className={`px-1 py-2 text-center ${isToday ? "bg-primary/5" : ""}`}>
                  <p className={`text-[10px] font-semibold uppercase ${isToday ? "text-primary" : isPast ? "text-muted-foreground/50" : "text-muted-foreground"}`}>
                    {DAY_SHORT_LT[i]}
                  </p>
                  <p className={`text-xs font-bold ${isToday ? "text-primary" : isPast ? "text-muted-foreground/50" : "text-foreground"}`}>
                    {parseInt(dd)}.{parseInt(mm)}
                  </p>
                </div>
              );
            })}
          </div>
          {/* Slot rows */}
          <div className="max-h-[400px] overflow-y-auto">
            {SLOTS.map(slot => {
              const slotMin = toMin(slot);
              return (
                <div key={slot} className="grid border-b border-border/40 last:border-0" style={{ gridTemplateColumns: `56px repeat(7, 1fr)` }}>
                  <div className="px-2 py-1 flex items-center justify-end text-[10px] tabular-nums font-mono text-muted-foreground shrink-0">
                    {slot}
                  </div>
                  {days.map(day => {
                    const isToday = day === today;
                    const nowMin = now.getHours() * 60 + now.getMinutes();
                    const isPast = day < today || (isToday && slotMin + 30 <= nowMin);
                    const booking = weeklyBookings.find(b => {
                      if (b.date !== day) return false;
                      return toMin(b.startTime) <= slotMin && toMin(b.endTime) > slotMin &&
                        ["confirmed", "pending", "blocked"].includes(b.status);
                    });
                    if (booking) {
                      return (
                        <div key={day} className="px-0.5 py-0.5">
                          <div
                            onClick={() => onBookingClick(booking)}
                            className={`h-7 rounded text-[9px] font-medium border cursor-pointer hover:opacity-75 transition-opacity flex items-center px-1 overflow-hidden ${
                              booking.status === "confirmed" ? "bg-blue-500/15 text-blue-700 dark:text-blue-300 border-blue-400/30"
                              : booking.status === "pending" ? "bg-amber-400/15 text-amber-700 dark:text-amber-300 border-amber-400/30"
                              : "bg-zinc-200 dark:bg-zinc-700/50 text-zinc-500 border-zinc-300/40"
                            }`}
                          >
                            <span className="truncate">{booking.customerName.split(" ")[0]}</span>
                          </div>
                        </div>
                      );
                    }
                    return (
                      <div key={day} className="px-0.5 py-0.5">
                        <div
                          onClick={() => !isPast && onFreeClick(day, slot)}
                          className={`h-7 rounded border border-dashed border-border/30 transition-colors flex flex-col items-center justify-center gap-0 ${
                            isToday && slotMin >= (now.getHours() * 60 + now.getMinutes() - 30) && slotMin < (now.getHours() * 60 + now.getMinutes() + 30) ? "bg-primary/5" : ""
                          } ${isPast ? "opacity-25" : "cursor-pointer hover:bg-muted/40 group"}`}
                        >
                          {(() => {
                            const p = todayPricing[slot] ?? (pricePerHour / 2);
                            return p > 0 ? (
                              <span className="text-[8px] text-muted-foreground/40 group-hover:text-muted-foreground/70 leading-none tabular-nums">
                                {p % 1 === 0 ? p : p.toFixed(1)}€
                              </span>
                            ) : null;
                          })()}
                        </div>
                      </div>
                    );
                  })}
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

function BookingInfoModal({ booking, onClose, courtId, onCancelled }: {
  booking: Booking; onClose: () => void; courtId: number; onCancelled?: () => void;
}) {
  const [, navigate] = useLocation();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const canCancel = ["confirmed", "pending", "blocked"].includes(booking.status);
  const note = booking.rentedItems ?? null;
  const hasEmail = booking.customerEmail && !booking.customerEmail.startsWith("manual-");

  const cancelMutation = useMutation({
    mutationFn: () => customFetch(`${API_URL}/bookings/${booking.id}`, { method: "DELETE" }),
    onSuccess: () => {
      toast({ title: booking.status === "blocked" ? "Laikas atblokuotas" : "Rezervacija atšaukta" });
      queryClient.invalidateQueries({ queryKey: ["owner-court-stats", String(courtId)] });
      onCancelled?.();
      onClose();
    },
    onError: (e: any) => toast({ title: "Klaida", description: e?.data?.error || e?.message || "Nepavyko atšaukti", variant: "destructive" }),
  });

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-card border border-border rounded-2xl shadow-2xl w-full max-w-sm p-6">
        <button onClick={onClose} className="absolute top-4 right-4 p-1 rounded hover:bg-muted transition-colors">
          <X className="h-4 w-4" />
        </button>
        <h2 className="text-lg font-bold mb-1">Rezervacija #{booking.id}</h2>
        <p className="text-sm text-muted-foreground mb-4">{booking.startTime.slice(0,5)}–{booking.endTime.slice(0,5)}</p>
        <div className="space-y-2 text-sm">
          <div className="flex justify-between"><span className="text-muted-foreground">Klientas</span><span className="font-medium">{booking.customerName}</span></div>
          {hasEmail && <div className="flex justify-between"><span className="text-muted-foreground">El. paštas</span><span className="font-medium truncate max-w-[60%] text-right">{booking.customerEmail}</span></div>}
          {booking.customerPhone && <div className="flex justify-between"><span className="text-muted-foreground">Telefonas</span><span className="font-medium">{booking.customerPhone}</span></div>}
          <div className="flex justify-between"><span className="text-muted-foreground">Data</span><span className="font-medium">{booking.date}</span></div>
          <div className="flex justify-between"><span className="text-muted-foreground">Laikas</span><span className="font-medium">{booking.startTime.slice(0,5)} – {booking.endTime.slice(0,5)}</span></div>
          <div className="flex justify-between"><span className="text-muted-foreground">Kaina</span><span className="font-medium">€{booking.totalPrice.toFixed(2)}</span></div>
          <div className="flex justify-between items-center">
            <span className="text-muted-foreground">Statusas</span>
            <Badge variant={booking.status === "confirmed" ? "default" : booking.status === "cancelled" ? "destructive" : "secondary"}>
              {STATUS_LT[booking.status] ?? booking.status}
            </Badge>
          </div>
          {note && (
            <div className="pt-1 border-t border-border/40">
              <p className="text-xs text-muted-foreground mb-0.5">Pastaba</p>
              <p className="text-sm">{note.startsWith("Pastaba: ") ? note.slice(9) : note}</p>
            </div>
          )}
        </div>
        <div className="flex flex-col gap-2 mt-5">
          {canCancel && (
            <Button
              variant="destructive"
              className="w-full text-sm"
              disabled={cancelMutation.isPending}
              onClick={() => cancelMutation.mutate()}
            >
              {cancelMutation.isPending ? "Atšaukiama…" : booking.status === "blocked" ? "Atblokuoti laiką" : "Atšaukti rezervaciją"}
            </Button>
          )}
          <div className="flex gap-2">
            <Button variant="outline" className="flex-1" onClick={onClose}>Uždaryti</Button>
            {booking.status !== "blocked" && (
              <Button className="flex-1" onClick={() => { onClose(); navigate(`/bookings/${booking.id}`); }}>
                Pilna peržiūra
              </Button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

function WeeklyCalendar({ weeklyBookings }: { weeklyBookings: Booking[] }) {
  const weekDates = getWeekDates();
  const today = todayStr();
  const byDate = new Map<string, Booking[]>();
  for (const d of weekDates) byDate.set(d, []);
  for (const b of weeklyBookings) {
    if (byDate.has(b.date)) byDate.get(b.date)!.push(b);
  }
  return (
    <div className="bg-card border border-border rounded-2xl p-4">
      <div className="flex items-center gap-2 mb-4">
        <CalendarDays className="w-4 h-4 text-primary" />
        <h3 className="font-semibold text-sm">Šios savaitės grafikas</h3>
      </div>
      <div className="grid grid-cols-7 gap-1.5">
        {weekDates.map((date, i) => {
          const bookings = byDate.get(date) ?? [];
          const isToday = date === today;
          const isPast = date < today;
          const confirmed = bookings.filter(b => b.status === "confirmed").length;
          const pending = bookings.filter(b => b.status === "pending").length;
          return (
            <div key={date} className={`rounded-xl p-2 text-center border transition-colors ${
              isToday ? "bg-primary/10 border-primary/30" : isPast ? "bg-muted/30 border-border/50" : "bg-muted/10 border-border"
            }`}>
              <p className={`text-[10px] font-medium uppercase ${isToday ? "text-primary" : "text-muted-foreground"}`}>{DAY_NAMES[i]}</p>
              <p className={`text-xs font-bold mb-1.5 ${isToday ? "text-primary" : "text-foreground"}`}>{fmtDate(date)}</p>
              {bookings.length === 0 ? (
                <p className="text-[10px] text-muted-foreground">–</p>
              ) : (
                <div className="space-y-0.5">
                  {confirmed > 0 && (
                    <div className="rounded bg-emerald-500/15 text-emerald-600 text-[10px] font-semibold px-1 py-0.5">
                      {confirmed} ✓
                    </div>
                  )}
                  {pending > 0 && (
                    <div className="rounded bg-amber-500/15 text-amber-600 text-[10px] font-semibold px-1 py-0.5">
                      {pending} ⏳
                    </div>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

function BookingRow({ booking }: { booking: Booking }) {
  const statusClass = STATUS_COLORS[booking.status] ?? "bg-muted text-muted-foreground border-border";
  const statusLabel = STATUS_LT[booking.status] ?? booking.status;
  return (
    <div className="flex items-center justify-between py-3 border-b border-border/60 last:border-0 gap-2">
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium truncate">{booking.customerName}</p>
        <p className="text-xs text-muted-foreground">
          {fmtDate(booking.date)} · {booking.startTime.slice(0,5)}–{booking.endTime.slice(0,5)}
